mapper.update:
UPDATE bike_after_sales_solution_version SET status=#{to}
    ,confirmed_by=#{operatorId},confirmed_at=CURRENT_TIMESTAMP(3)
    ,approved_by=#{operatorId},approved_at=CURRENT_TIMESTAMP(3)
    WHERE id=#{id} AND status=#{from}

UPDATE bike_after_sales_return SET status=#{status},revision=revision+1,updated_by=#{operatorId},updated_at=CURRENT_TIMESTAMP(3)
,warehouse_name=#{request.warehouseName},recipient=#{request.recipient},phone=#{request.phone},address_line=#{request.addressLine},postal_code=#{request.postalCode}
,carrier=#{request.carrier},tracking_no=#{request.trackingNo},sent_at=CURRENT_TIMESTAMP(3)
,received_at=CURRENT_TIMESTAMP(3)
,inspection_result=#{request.inspectionResult},inspected_at=CURRENT_TIMESTAMP(3)
,disposition_note=#{request.reason}
,completed_at=CURRENT_TIMESTAMP(3)
WHERE shipment_id=#{shipmentId} AND case_id=#{caseId} AND revision=#{request.revision}

UPDATE bike_after_sales_case_contact SET
    contact_name=#{contact.contactName},contact_phone=#{contact.contactPhone},contact_email=#{contact.contactEmail},country_code=#{contact.countryCode},region=#{contact.region},city=#{contact.city},address_line=#{contact.addressLine},postal_code=#{contact.postalCode},snapshot_source='MANUAL',
    end_customer_purchase_date=#{endDate}COALESCE(#{endDate},end_customer_purchase_date) WHERE case_id=#{caseId}
